import solid.service.notification.NotificationService;
import solid.persistence.drivers.PostgresDriver;
import solid.service.UserService;
import solid.user.AdminUser;
import solid.user.User;

public class Main {
    public static void main(String[] args) {
        System.out.println("------------------Adding users-------------------------");
        // Create User instances
        User user1 = new User(1, "john_doe", 25, 100000);
        User user2 = new User(2, "alice_smith", 35, 100000);
        User user3 = new AdminUser(0, "bob_jones", 65, 100000, true);

        PostgresDriver postgresDriver = new PostgresDriver();
        UserService userService = new UserService(postgresDriver);
        NotificationService notificationService = new NotificationService();

        // Save users 1 and 2 using RegularUserService
        userService.addUser(user1);
        userService.addUser(user2);
        userService.addUser(user3);

        System.out.println("\n------------------Sending notifications-------------------------");

        // Send notifications using different services
        notificationService.sendTaxNotification(user1, "Pay your taxes!", "EMAIL");
        notificationService.sendTaxNotification(user2, "Pay your taxes!", "SMS");
        // regularUserService.sendTaxNotification(user2, "Pay your taxes!", "PUSH");
        // //This breaks the code

        notificationService.sendTaxNotification(user3, "Pay your taxes!", "PUSH");

        System.out.println("\n------------------Fetching users-------------------------");

        // Fetch and display user by ID -> there is an encapsulation violation here ->
        // bug proneness
        userService.getUserById(1);
        userService.getUserById(0);

        System.out.println("\n------------------Deleting users-------------------------");
        // Delete accounts
        userService.removeUser(user1);
        userService.removeUser(user2);
        if (user3 instanceof AdminUser) {
            AdminUser adminUser = (AdminUser) user3;
            if (!adminUser.hasSuperAdminRights()) {
                userService.removeUser(adminUser);
            } else {
                System.out.println("Cannot delete admin user with super admin rights: " + adminUser.getUsername());
            }
        } else {
            userService.removeUser(user3);
        }

    }
}

package solid.user;

public class User {
    private int id;
    private String username;
    private int age;
    private double salary;

    // Constructor
    public User(int id, String username, int age, double salary) {
        this.id = id;
        this.username = username;
        this.age = age;
        this.salary = salary;
    }

    // Method to calculate tax based on age and salary
    public double calculateTax() {
        double taxRate;
        if (age < 30) {
            taxRate = 0.10; // 10% tax rate
        } else if (age <= 60) {
            taxRate = 0.20; // 20% tax rate
        } else {
            taxRate = 0.15; // 15% tax rate
        }
        return salary * taxRate;
    }

    // Regular users can delete themselves
    public void deleteAccount() {
        System.out.println("User account deleted: " + username);
    }

    // Getters and setters (optional, for accessing private fields)
    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public int getAge() {
        return age;
    }

    public void setAge(int age) {
        this.age = age;
    }

    @Override
    public String toString() {
        return "User{" +
                "id=" + id +
                ", username='" + username + '\'' +
                ", age=" + age +
                ", salary=" + salary +
                '}';
    }
}

package solid.user;

/**
 * Why This Violates the Liskov Substitution Principle:
 * <ul>
 * <li><b>Unexpected Behavior Change:</b> The <code>AdminUser</code> class
 * overrides the <code>deleteAccount</code> method
 * to provide different behavior. For regular users, the
 * <code>deleteAccount</code> method always deletes the user account,
 * but for <code>AdminUser</code>, the deletion is conditional
 * (<code>if (hasSuperAdminRights)</code>), meaning the behavior
 * is not consistent with the parent class.</li>
 * <li><b>Client Code Assumptions Broken:</b> Any client code that relies on the
 * <code>deleteAccount</code> method to
 * always delete an account will break if it encounters an
 * <code>AdminUser</code> with super admin rights. This violates the
 * Liskov Substitution Principle because the subclass (<code>AdminUser</code>)
 * cannot fully substitute the superclass
 * (<code>User</code>) without altering the program's expected behavior.</li>
 * </ul>
 */

public class AdminUser extends User {
    private boolean hasSuperAdminRights;

    public AdminUser(int id, String username, int age, double salary, boolean hasSuperAdminRights) {
        super(id, username, age, salary);
        this.hasSuperAdminRights = hasSuperAdminRights;
    }

    public boolean hasSuperAdminRights() {
        return hasSuperAdminRights;
    }
}

package solid.persistence;

import solid.user.User;

public interface DatabaseDriver {
    boolean save(User user);

    User query(int id);

    boolean delete(int id);
}

package solid.service;

import solid.persistence.DatabaseDriver;
import solid.user.User;

/**
 * Why This Violates the Interface Segregation Principle (ISP):
 * <ul>
 * <li><b>Forces Irrelevant Implementations:</b> The
 * <code>RegularUserService</code> class is forced to implement
 * methods (<code>sendEmailNotification</code>,
 * <code>sendSMSNotification</code>, <code>sendPushNotification</code>)
 * that it does not need or use.</li>
 * <li><b>Unsupported Operations:</b> The class throws
 * <code>UnsupportedOperationException</code> for some of these methods,
 * which is a clear sign that it is being forced to implement methods that are
 * not relevant to its role.</li>
 * <li><b>Low Cohesion:</b> The <code>UserOperations</code> interface is too
 * broad and covers multiple
 * responsibilities (user management and notification sending), which are
 * unrelated for some implementing classes.</li>
 * </ul>
 *
 * <p>
 * Why This Violates the Dependency Inversion Principle (DIP):
 * </p>
 * <ul>
 * <li><b>High-Level Module Depends on Low-Level Module:</b> The
 * <code>UserService</code> class directly depends on the
 * concrete <code>PostgresDriver</code> class. This makes it difficult to change
 * the database layer without modifying the
 * <code>UserService</code> class.</li>
 * <li><b>Lack of Abstractions:</b> There is no abstraction or interface that
 * defines the behavior of a database driver,
 * making the <code>UserService</code> class tightly coupled to the
 * <code>PostgresDriver</code>.</li>
 * </ul>
 *
 * <p>
 * Why This Violates the Open-Closed Principle (OCP):
 * </p>
 * <ul>
 * <li><b>Modification Required for Each New Notification Type:</b> Every time a
 * new notification type is needed
 * (e.g., "In-App Message" or "Webhook"), you must modify the
 * <code>sendNotification</code> method to add a new
 * <code>else if</code> block and create a corresponding method for the new
 * notification type.</li>
 * <li><b>High Risk of Errors:</b> Frequent modifications increase the risk of
 * introducing bugs, especially if the existing
 * code is already complex.</li>
 * <li><b>Difficult to Test and Maintain:</b> As more notification types are
 * added, the <code>NotificationService</code> class
 * becomes harder to test and maintain due to its increasing size and
 * complexity.</li>
 * </ul>
 *
 * <p>
 * Why This Violates the Single Responsibility Principle (SRP):
 * </p>
 * <ul>
 * <li><b>Managing User Data:</b> The <code>RegularUserService</code> class has
 * methods like <code>createUser</code> and
 * <code>deleteUser</code> that handle user data in the database.</li>
 * <li><b>Sending Notifications:</b> The class also contains methods like
 * <code>sendWelcomeEmail</code> and
 * <code>sendPasswordResetEmail</code> that are responsible for sending
 * different types of emails.</li>
 * </ul>
 */

public class UserService implements UserOperations {
    private final DatabaseDriver databaseDriver;

    public UserService(DatabaseDriver databaseDriver) {
        this.databaseDriver = databaseDriver;
    }

    public User getUserById(int id) {
        User fetchedUser = databaseDriver.query(id);

        if (fetchedUser == null) {
            System.out.println("User with ID " + id + " not found.");
            return null;
        }
        System.out.println("Fetched User: " + fetchedUser.getUsername() + ", " + fetchedUser.getAge() + "\n");
        return fetchedUser;
    }

    @Override
    public void addUser(User user) {
        databaseDriver.save(user);
    }

    @Override
    public void removeUser(User user) {
        boolean del = databaseDriver.delete(user.getId());
        if (del) {
            user.deleteAccount();
            System.out.println("Account deleted successfully.\n");
        } else {
            System.out.println("User with id " + user.getId() + " not found!\n");
        }
    }
}

package solid.service;

import solid.user.User;

/**
 * Low Cohesion:</b> The <code>UserOperations</code> interface is too broad and
 * covers multiple
 * responsibilities (user management and notification sending), which are
 * unrelated for some implementing classes.
 */
public interface UserOperations {
    void addUser(User user);

    void removeUser(User user);
}

package solid.persistence.drivers;

import solid.persistence.DatabaseDriver;
import solid.user.User;

import java.util.HashMap;

public class PostgresDriver implements DatabaseDriver {
    private static HashMap<Integer, User> users = new HashMap<>();

    // Method to simulate a database query
    public boolean save(User user) {
        System.out.println("Executing Save SQL: " + user);

        // Here, you would typically execute the query against a real PostgreSQL
        // database and return a ResultSet.
        // This is just a simulation, so we'll return a list with the queried users.
        users.put(user.getId(), user);

        return true;
    }

    public User query(int id) {
        System.out.println("Executing SQL query");
        try {
            return users.get(id);
        } catch (IndexOutOfBoundsException e) {
            return null;
        }
    }

    public boolean delete(int id) {
        System.out.println("Executing SQL delete");
        try {
            users.remove(id);
            return true;
        } catch (IndexOutOfBoundsException e) {
            return false;
        }
    }
}

