package solid.service.notification;

import solid.user.User;

public class NotificationService {

    public void sendTaxNotification(User user, String message, String notificationType) {
        message = message + " Value: " + user.calculateTax();
        NotificationSender sender = NotificationSenderFactory.getSender(notificationType);
        sender.sendNotification(user, message);
    }
}

package solid.service.notification;

import solid.user.User;

public class PushNotificationSender implements NotificationSender {

    @Override
    public void sendNotification(User user, String message) {
        System.out.println("Sending PUSH to " + user.getUsername() + " -> " + message);
    }
}

package solid.service.notification;

import solid.user.User;

public interface NotificationSender {
    void sendNotification(User user, String message);
}

package solid.service.notification;

public class NotificationSenderFactory {

    public static NotificationSender getSender(String notificationType) {
        switch (notificationType.toUpperCase()) {
            case "EMAIL":
                return new EmailNotificationSender();
            case "SMS":
                return new SMSNotificationSender();
            case "PUSH":
                return new PushNotificationSender();
            default:
                throw new IllegalArgumentException("Unknown notification type: " + notificationType);
        }
    }
}


